mexico:{quick:["<b>Topes</b>: lomos de toro altísimos con letrero propio, en casi toda entrada de pueblo","Fachadas de locales <b>pintadas con publicidad</b> en colores fuertes (Coca-Cola, Tecate, Corona)","Postes de hormigón de sección cuadrada con perforaciones, además de postes de madera","Señalización en español con letreros verdes en las carreteras federales"]},
guatemala:{quick:["<b>Chicken buses</b>: buses escolares estadounidenses repintados con colores vibrantes y cromados","<b>Volcanes cónicos</b> perfectos en el horizonte del altiplano","Mujeres con <b>huipiles</b> (blusas bordadas) y tejidos mayas muy coloridos","Montañas empinadas con maíz plantado hasta en laderas casi verticales"]},
"costa-rica":{quick:["Vegetación <b>tropical densa y muy verde</b>, con palmeras y bosque nuboso","<b>Cercos hechos de árboles vivos</b> (postes que brotan hojas) en zonas rurales","Casas con <b>rejas blancas</b> en ventanas y terrazas, techo de zinc de colores","Patentes con franja azul y 'CR'; sin ejército y con mucha señalización ambiental"]},
panama:{quick:["<b>Skyline de rascacielos</b> en Ciudad de Panamá, algo raro en Centroamérica","Uso del <b>dólar estadounidense</b> junto al balboa; precios en US$","Vegetación tropical densa y clima húmedo en casi todo el territorio","La Panamericana como eje principal, con el tapón del Darién infranqueable al este"]},
colombia:{quick:["Patentes <b>amarillas</b> con letras negras","Tres ramas de los Andes atravesando el país, con valles profundos entre ellas","Motos en cantidad enorme y mototaxis en ciudades pequeñas","Casas de bloque pintadas en colores vivos con teja o zinc"]},
ecuador:{quick:["Tres mundos a poca distancia: costa cálida, sierra andina alta y selva amazónica","<b>Volcanes nevados</b> (Cotopaxi, Chimborazo) visibles desde el altiplano","Uso del <b>dólar estadounidense</b> como moneda oficial; precios en US$","Patentes con la bandera ecuatoriana y la provincia en la letra inicial"]},
peru:{quick:["<b>Costa desértica</b> gris y sin vegetación, con arena llegando hasta el mar","Casas de <b>ladrillo rojo a la vista y sin terminar</b>, con fierro expuesto, muy comunes","Mototaxis de tres ruedas con toldo en las ciudades pequeñas","Andes con terrazas incas y altiplano sobre los 3.500 m"]},
bolivia:{quick:["<b>Altiplano</b> muy alto (3.700 m o más), seco, con montañas nevadas al fondo","Casas de <b>ladrillo rojo a la vista</b> sin revoque, cubriendo laderas enteras en El Alto","Mujeres con <b>sombrero bombín</b> y pollera en las ciudades andinas","Cobertura irregular: muchos caminos sin imagen y tramos de baja calidad"]},
chile:{quick:["Los <b>Andes siempre al este</b>: el país tiene en promedio 180 km de ancho","Bolardos blancos con reflectante e infraestructura en buen estado","Letreros y señalización en español, con estándar ordenado y moderno","Norte: desierto de Atacama absoluto. Sur: bosque húmedo, lagos y volcanes"]},
argentina:{quick:["Patente del <b>Mercosur</b> con franja azul y las letras <b>AR</b>","<b>Pampa</b>: llanura absolutamente plana con ganado, maíz y soja","Hileras de <b>eucaliptos y álamos</b> plantados como cortavientos en las estancias","Postes de hormigón y cercos de alambre con postes de madera junto a las rutas"]},
uruguay:{quick:["Patente del Mercosur con <b>UY</b>: la diferencia más directa con Argentina","Terreno <b>suavemente ondulado</b> con pastizal y ganado, sin montañas","<b>Palmeras butiá</b> aisladas en campo abierto al este del país","Postes de hormigón y cercos de alambre; muchas rutas rectas y vacías"]},
brazil:{quick:["<b>Portugués</b> con patente del Mercosur marcada <b>BR</b>","<b>Tierra roja</b> intensa en São Paulo, Paraná y Minas; suelo más claro en el nordeste","Postes de hormigón <b>redondos y cónicos</b>, muy comunes en carreteras estatales","Letreros de carretera con el patrón 'BR-101', 'SP-330', 'MG-050' en escudo propio"]},
"dominican-republic":{quick:["Casas de <b>madera pintadas en colores vivos</b> con terraza y techo de zinc","<b>Motoconchos</b> (mototaxis) en gran cantidad","Vegetación tropical con cocoteros, mangos y cañaverales","Español en los letreros, en contexto insular caribeño"]},
"puerto-rico":{quick:["<b>Señalización estadounidense</b> (rombos amarillos, escudos de ruta) con texto en <b>español</b>","Distancias en <b>kilómetros</b> pero límites de velocidad en <b>millas por hora</b>","Postes de madera y hormigón al estilo estadounidense, con mucho cableado","Vegetación tropical densa, con bosque en El Yunque y cocoteros en la costa"]},
curacao:{quick:["Arquitectura <b>colonial neerlandesa</b> pintada en colores vivos con frontones curvos","Vegetación <b>árida</b>: cactus, arbustos espinosos y divi-divi torcidos por el viento","<b>Papiamento</b> en letreros y comercios, mezclado con neerlandés","Isla pequeña, plana y seca, rodeada de mar turquesa"]},
bermuda:{quick:["<b>Techos blancos escalonados</b> de caliza, diseñados para captar agua lluvia: exclusivos de Bermudas","Casas en <b>tonos pastel</b> (rosa, celeste, amarillo) con techo blanco","Manejo por la <b>izquierda</b>, con un máximo de 35 km/h en toda la isla","Muchas motonetas y pocos autos; cedros de Bermudas e hibiscos"]},

australia:{quick:["<b>Eucaliptos</b> en prácticamente toda la vegetación nativa, con follaje ralo y verde grisáceo","Manejo por la <b>izquierda</b> con advertencias en <b>rombo amarillo</b>","Postes de madera con aisladores y <b>buzones sobre poste</b> frente a las casas rurales","Tierra roja intensa en el Outback; pasto seco y dorado casi todo el año"]},
"new-zealand":{quick:["Nombres <b>maoríes</b> con secuencias de vocales: 'Whangarei', 'Taupō', 'Kaikoura', 'Aotearoa'","Lomas <b>verdes y onduladas</b> con ovejas y cercos eléctricos","<b>Helechos arbóreos</b> (ponga) y vegetación de bosque templado húmedo","Manejo por la izquierda; advertencias en rombo amarillo"]},
guam:{quick:["<b>Señalización estadounidense</b> (rombos amarillos, grifos, escudos de ruta) en ambiente tropical","Nombres <b>chamorros</b> con apóstrofos y tildes: 'Hagåtña', 'Yigo', 'Dededo'","Postes de madera u hormigón al estilo estadounidense, con transformadores","Vegetación tropical con selva densa, cocoteros y pasto espada"]},
"american-samoa":{quick:["<b>Fales</b>: construcciones abiertas con techo ovalado sobre pilares, sin paredes","<b>Iglesias blancas grandes</b> y desproporcionadas al tamaño de los pueblos","Montañas volcánicas muy empinadas y verdes cayendo directo al mar","Letreros estadounidenses con nombres samoanos; manejo por la derecha"]},
"christmas-island":{quick:["Patentes <b>australianas</b> con el nombre del territorio escrito","Manejo por la <b>izquierda</b> en una isla tropical del océano Índico","Templos chinos y mezquitas malayas en comunidades muy pequeñas","Letreros de advertencia sobre la <b>migración de cangrejos rojos</b> en Isla de Navidad"]}
